-- Generated by write_sql.py. Re-run generate_data.py after regenerating the CSVs.
-- 1. Copy the csv folder to the SQL Server machine, for example C:\DigitalBankData\
-- 2. Edit @DataPath below. The SQL Server service account must be able to read that folder.
-- 3. Run 00, then 01, then this script, then 03, then 04.
-- Line endings in the CSVs are LF. A trailing CR is stripped, so a CRLF copy still loads.

USE DigitalBankDW;
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @DataPath nvarchar(400) = N'C:\DigitalBankData\';
DECLARE @sql nvarchar(max);
DECLARE @actual int;
DECLARE @msg nvarchar(400);

IF RIGHT(@DataPath, 1) <> N'\'
    SET @DataPath += N'\';

IF EXISTS (SELECT 1 FROM dbo.DimCustomer)
    THROW 50001, N'Tables are not empty. Run 01_create_tables.sql before loading again.', 1;

TRUNCATE TABLE stg.DimCustomer;
SET @sql = N'BULK INSERT stg.DimCustomer
    FROM ''' + @DataPath + N'DimCustomer.csv''
    WITH (FIRSTROW = 2, FIELDTERMINATOR = '','', ROWTERMINATOR = ''0x0a'', TABLOCK, KEEPNULLS);';
EXEC (@sql);
SET @actual = (SELECT COUNT(*) FROM stg.DimCustomer);
IF @actual <> 50000
BEGIN
    SET @msg = N'DimCustomer.csv loaded ' + CAST(@actual AS nvarchar(20)) + N' rows, expected 50000.';
    THROW 50002, @msg, 1;
END;
INSERT INTO dbo.DimCustomer ([CustomerKey], [CustomerID], [CNICToken], [AgeBand], [Gender], [Occupation], [Province], [City], [UrbanRural], [MobileNetwork], [DeviceOS], [DeviceBrand], [AppVersion], [SignupDate], [SignupDateKey])
SELECT
