BEGIN
    SET @msg = N'FactPayments_202609.csv could not be converted into dbo.FactPayments. A blank landed in a required column or a value was not a valid type.';
    THROW 50003, @msg, 1;
END;

TRUNCATE TABLE stg.FactPayments;
SET @sql = N'BULK INSERT stg.FactPayments
    FROM ''' + @DataPath + N'FactPayments_202610.csv''
    WITH (FIRSTROW = 2, FIELDTERMINATOR = '','', ROWTERMINATOR = ''0x0a'', TABLOCK, KEEPNULLS);';
